113	static void
114	proj_on_basis(const gkyl_proj_powsqrt_on_basis *up, const struct gkyl_array *fun_at_ords, double* f)
115	{
116	  int num_basis = up->num_basis;
117	  int tot_quad = up->tot_quad;
118	
119	  const double* GKYL_RESTRICT weights = up->weights->data;
120	  const double* GKYL_RESTRICT basis_at_ords = up->basis_at_ords->data;
121	  const double* GKYL_RESTRICT func_at_ords = fun_at_ords->data;
122	
123	  for (int k=0; k<num_basis; ++k) f[k] = 0.0;
124	
125	  for (int imu=0; imu<tot_quad; ++imu) {
126	    double tmp = weights[imu]*func_at_ords[imu];
127	    for (int k=0; k<num_basis; ++k)
128	      f[k] += tmp*basis_at_ords[k+num_basis*imu];
129	  }
130	}
