133	gkyl_proj_powsqrt_on_basis_advance(const gkyl_proj_powsqrt_on_basis *up,
134	  const struct gkyl_range *range, double expIn, const struct gkyl_array *fIn,
135	  struct gkyl_array *fOut)
136	{
137	#ifdef GKYL_HAVE_CUDA
138	  if (up->use_gpu)
139	    return gkyl_proj_powsqrt_on_basis_advance_cu(up, range, expIn, fIn, fOut);
140	#endif
141	
142	  // Create range to loop over quadrature points.
143	  struct gkyl_range qrange = get_qrange(up->ndim, up->num_quad);
144	
145	  struct gkyl_range_iter iter;
146	  gkyl_range_iter_init(&iter, range);
147	  while (gkyl_range_iter_next(&iter)) {
148	    long linidx = gkyl_range_idx(range, iter.idx);
149	
150	    const double *fIn_d = gkyl_array_cfetch(fIn, linidx);
151	
152	    struct gkyl_range_iter qiter;
153	    gkyl_range_iter_init(&qiter, &qrange);
154	    while (gkyl_range_iter_next(&qiter)) {
155	      
156	      int qidx = gkyl_range_idx(&qrange, qiter.idx);
157	
158	      // Evaluate input function f at quad point.
159	      const double *b_ord = gkyl_array_cfetch(up->basis_at_ords, qidx);
160	      double fIn_q=0.;
161	      for (int k=0; k<up->num_basis; ++k)
162	        fIn_q += fIn_d[k]*b_ord[k];
163	
164	      double *fOut_q = gkyl_array_fetch(up->fun_at_ords, qidx);
165	
166	      // Evaluate pow(sqrt()) at quad point.
167	      fOut_q[0] = (fIn_q < 0.) ? 1.e-40 : pow(sqrt(fIn_q), expIn);
168	    }
169	
170	    // Compute expansion coefficients.
171	    proj_on_basis(up, up->fun_at_ords, gkyl_array_fetch(fOut, linidx));
172	  }
